<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.22);
      --text: #e5eefb;
      --muted: #9fb0cc;
      --accent: #7c9cff;
      --accent-strong: #9bb3ff;
      --input: rgba(15, 23, 42, 0.95);
      --input-border: rgba(148, 163, 184, 0.3);
      --error: #ff8f8f;
      --error-border: rgba(255, 143, 143, 0.75);
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
