      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .page-shell {
      width: min(100%, 560px);
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
      padding: 32px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 12px;
      border-radius: 999px;
      background: rgba(124, 156, 255, 0.12);
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 600;
      letter-spacing: 0.02em;
      margin-bottom: 18px;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 4vw, 2.5rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
    }

    input {
      width: 100%;
      border: 1px solid var(--input-border);
      border-radius: 14px;
      background: var(--input);
      color: var(--text);
      padding: 14px 16px;
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    input::placeholder {
      color: #7083a6;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.18);
    }

    input[aria-invalid="true"] {
      border-color: var(--error-border);
      box-shadow: 0 0 0 4px rgba(255, 143, 143, 0.12);
    }

    .helper-text,
    .validation-message {
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .validation-message {
      color: var(--error);
      min-height: 1.3em;
    }

    .actions {
      display: flex;
