      background: linear-gradient(135deg, var(--accent) 0%, #5e7bff 100%);
      color: #091224;
      font: inherit;
      font-weight: 700;
      padding: 14px 20px;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
      box-shadow: 0 14px 30px rgba(94, 123, 255, 0.28);
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.05);
    }

    button:focus-visible {
      outline: 3px solid rgba(124, 156, 255, 0.4);
      outline-offset: 2px;
    }

    .status-message {
      min-height: 1.4em;
      color: #9ed7ae;
      font-size: 0.95rem;
    }

    @media (max-width: 640px) {
      .page-shell {
        padding: 24px;
