      .actions {
        flex-direction: column;
        align-items: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const root = document.getElementById("app");

    const formState = {
      fullName: "",
      email: "",
      phone: "",
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false,
      statusMessage: ""
    };

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
    const fields = [
      {
        name: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Jordan Lee",
        required: true
      },
      {
        name: "email",
        label: "Email address",
        type: "email",
        placeholder: "jordan@example.com",
        required: true
      },
      {
        name: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "+1 (555) 123-4567",
        helperText: "Optional. Use digits with spaces, dashes, parentheses, or a leading +, for example +1 (555) 123-4567.",
        required: false
      }
    ];

    function validateField(name, value) {
      const trimmedValue = value.trim();

      if (name === "fullName") {
        if (!trimmedValue) {
          return "Full name is required.";
        }
      }

      if (name === "email") {
        if (!trimmedValue) {
          return "Email address is required.";
        }

        if (!emailPattern.test(trimmedValue)) {
          return "Enter a valid email address.";
        }
      }

      if (name === "phone" && trimmedValue && !phonePattern.test(trimmedValue)) {
        return "Enter a valid phone number using digits and optional separators.";
      }

      return "";
    }

    function getError(name) {
      const shouldShow = formState.submitted || formState.touched[name];
      return shouldShow ? validateField(name, formState[name]) : "";
    }

    function FormField(config) {
      const error = getError(config.name);
      const helperId = config.helperText ? config.name + "-helper" : "";
      const errorId = config.name + "-error";
      const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${config.name}">${config.label}${config.required ? " *" : ""}</label>
          <input
            id="${config.name}"
            name="${config.name}"
            type="${config.type}"
            placeholder="${config.placeholder}"
            value="${escapeHtml(formState[config.name])}"
            ${config.required ? "required" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            aria-invalid="${error ? "true" : "false"}"
          />
          ${config.helperText ? `<div class="helper-text" id="${helperId}">${config.helperText}</div>` : ""}
          <div class="validation-message" id="${errorId}" role="alert">${error}</div>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <form id="support-form" novalidate>
          ${fields.map(FormField).join("")}
          <div class="actions">
            <button type="submit">Submit</button>
            <div class="status-message" aria-live="polite">${formState.statusMessage}</div>
          </div>
        </form>
      `;
    }

    function SupportPage() {
      return `
        <main class="page-shell">
          <div class="eyebrow">Support team</div>
          <h1>Contact support</h1>
          <p class="intro">
            Send us your details and a member of our support team will follow up with the right next step.
          </p>
          ${ContactForm()}
        </main>
      `;
    }

    function App() {
      return SupportPage();
    }

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function render() {
      root.innerHTML = App();
      attachEvents();
      syncFormUi();
    }

    function syncFieldUi(fieldName) {
      const input = document.getElementById(fieldName);
      const errorElement = document.getElementById(fieldName + "-error");
      const error = getError(fieldName);

      input.value = formState[fieldName];
      input.setAttribute("aria-invalid", error ? "true" : "false");
      errorElement.textContent = error;
    }

    function syncFormUi() {
      fields.forEach((field) => syncFieldUi(field.name));
      document.querySelector(".status-message").textContent = formState.statusMessage;
    }

    function attachEvents() {
      const form = document.getElementById("support-form");
      const inputs = form.querySelectorAll("input");

      inputs.forEach((input) => {
        input.addEventListener("input", (event) => {
          formState[event.target.name] = event.target.value;
          formState.statusMessage = "";
          syncFieldUi(event.target.name);
          document.querySelector(".status-message").textContent = formState.statusMessage;
        });

        input.addEventListener("blur", (event) => {
          formState.touched[event.target.name] = true;
          syncFieldUi(event.target.name);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        formState.submitted = true;
        formState.touched.fullName = true;
        formState.touched.email = true;
        formState.touched.phone = true;

        const errors = ["fullName", "email", "phone"].map((fieldName) =>
          validateField(fieldName, formState[fieldName])
        );

        if (errors.some(Boolean)) {
          formState.statusMessage = "";
          syncFormUi();
          return;
        }

        formState.statusMessage = "Your request is ready to send.";
        syncFormUi();
      });
    }

    render();
  </script>
</body>
</html>
